/// <summary>
/// PricingAttribute of table <c>CustTable</c> field CreditMax.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::Customer, UPSPricingAttributeSourceLevel::Header)]
internal class UPSPricingAttributeCustTableCreditMax extends UPSPricingAttributeCustTable implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(CustTable, CreditMax);
}

public Set getAllowedValues()
{
    var         ret = new Set(Types::Real);
    CustTable   custTable;

    while select CreditMax from custTable
        group by CreditMax
    {
        ret.add(custTable.CreditMax);
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(CustTable, CreditMax));
    qbr.value(queryValue(_value));
}
